import ast, glob, os, sys
mods = {os.path.basename(f)[:-3] for f in glob.glob("_tools/*.py")}
g = {}
for f in glob.glob("_tools/ql_*.py") + glob.glob("_tools/bl_*.py"):
    m = os.path.basename(f)[:-3]
    s = set()
    for n in ast.walk(ast.parse(open(f, encoding="utf-8").read())):
        if isinstance(n, ast.Import): s |= {a.name for a in n.names if a.name in mods}
        elif isinstance(n, ast.ImportFrom) and n.module in mods: s.add(n.module)
    g[m] = {x for x in s if x[:3] == m[:3] and x != m}
def reach(a):
    seen, todo = set(), [a]
    while todo:
        for y in g.get(todo.pop(), ()):
            if y not in seen: seen.add(y); todo.append(y)
    return seen
cyc = sorted(m for m in g if m in reach(m))
print("bl_/ql_ modules in an import cycle (function-level imports included):", cyc)
sys.exit(1 if cyc else 0)
